begin;
with j as (select * from jsonb_to_recordset($law7d0066$[{"code_id":"NK_RF","article_number":"93","version_date":"2000-07-31","article_text":"В случае нахождения должностного лица налогового органа, проводящего налоговую проверку, на территории проверяемого лица требование о представлении документов передается руководителю (законному или уполномоченному представителю) организации или физическому лицу (его законному или уполномоченному представителю) лично под расписку. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ) (В редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nЕсли указанным способом требование о представлении документов передать невозможно, оно направляется в порядке, установленном пунктом 4 статьи 31 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Пункт в редакции федеральных законов от 27.07.2010 № 229-ФЗ)\n\nПредставление документов на бумажном носителе производится в виде заверенных проверяемым лицом копий. Не допускается требование нотариального удостоверения копий документов, представляемых в налоговый орган (должностному лицу), если иное не предусмотрено законодательством Российской Федерации. Листы документов, представляемых на бумажном носителе, должны быть пронумерованы и прошиты в соответствии с требованиями, утверждаемыми федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\nПредставление документов, составленных в электронной форме по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, осуществляется по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nИстребуемые документы, составленные на бумажном носителе, могут быть представлены в налоговый орган в электронной форме в виде электронных образов документов (документов на бумажном носителе, преобразованных в электронную форму путем сканирования с сохранением их реквизитов) по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов, по телекоммуникационным каналам связи или через личный кабинет налогоплательщика.\n\nВ случае представления истребуемых документов в налоговый орган в электронной форме по телекоммуникационным каналам связи такие документы должны быть заверены усиленной квалифицированной электронной подписью проверяемого лица или усиленной квалифицированной электронной подписью его представителя.\n\nПорядок направления требования о представлении документов и порядок представления документов по требованию налогового органа в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо через информационные системы организации, к которым предоставлен доступ налоговому органу, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (В редакции  Федерального закона от 31.07.2023 № 389-ФЗ)\n\nВ случае необходимости должностное лицо налогового органа вправе ознакомиться с подлинниками документов.\n\n(Пункт в редакции Федерального закона от 01.05.2016 № 130-ФЗ)\n\nВ случае, если проверяемое лицо не имеет возможности представить истребуемые документы в течение установленного настоящим пунктом срока, оно в течение дня, следующего за днем получения требования о представлении документов, письменно уведомляет проверяющих должностных лиц налогового органа о невозможности представления в указанные сроки документов с указанием причин, по которым истребуемые документы не могут быть представлены в установленные сроки, и о сроках, в течение которых проверяемое лицо может представить истребуемые документы. (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\nУказанное уведомление может быть представлено в налоговый орган проверяемым лицом лично или через представителя либо передано в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика. Лица, на которых в соответствии с пунктом 3 статьи 80 настоящего Кодекса не возложена обязанность по представлению налоговой декларации в электронной форме, вправе направить указанное уведомление по почте заказным письмом. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\nФорма и формат указанного уведомления в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 240-ФЗ)\n\nВ течение двух дней со дня получения такого уведомления руководитель (заместитель руководителя) налогового органа вправе на основании этого уведомления продлить сроки представления документов или отказать в продлении сроков, о чем выносится отдельное решение.\n\nПри проведении налоговой проверки консолидированной группы налогоплательщиков продление сроков осуществляется не менее чем на 10 дней. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\nВ случае такого отказа или непредставления указанных документов в установленные сроки должностное лицо налогового органа, проводящее налоговую проверку, производит выемку необходимых документов в порядке, предусмотренном статьей 94 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 27.07.2006 № 137-ФЗ)","article_title":"Статья 93. Истребование документов при проведении налоговой проверки","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"522ee84b65246ebbbe618a02eff35f5a80c3278bdf2e755baa4f7b0f6cf1bad4"},{"code_id":"NK_RF","article_number":"93.1","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 03.07.2016 № 243-ФЗ)\n\nИстребование документов (информации), касающихся деятельности проверяемого налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), может проводиться также при рассмотрении материалов налоговой проверки на основании решения руководителя (заместителя руководителя) налогового органа о проведении дополнительных мероприятий налогового контроля.  (В редакции  федеральных законов от 23.07.2013 № 248-ФЗ, от 03.07.2016 № 243-ФЗ, от 31.07.2023 № 389-ФЗ)\n\nДолжностное лицо налогового органа, проводящее налоговый мониторинг, вправе истребовать у контрагента или иных лиц, располагающих документами (информацией), касающимися деятельности организации, в отношении которой проводится налоговый мониторинг, эти документы (информацию). (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n11. При проведении камеральной налоговой проверки расчета финансового результата инвестиционного товарищества, налоговой декларации (расчета) по налогу на прибыль организаций, налогу на доходы физических лиц участника договора инвестиционного товарищества налоговый орган вправе истребовать у участника договора инвестиционного товарищества - управляющего товарища, ответственного за ведение налогового учета, следующие сведения за проверяемый период:\n\n1) состав участников договора инвестиционного товарищества, включая сведения об изменениях состава участников указанного договора;\n\n2) состав участников договора инвестиционного товарищества - управляющих товарищей, включая сведения об изменениях состава таких участников указанного договора;\n\n3) доля прибыли (расходов, убытков), приходящаяся на каждого из управляющих товарищей и товарищей;\n\n4) доля участия каждого из управляющих товарищей и товарищей в прибыли инвестиционного товарищества, установленная договором инвестиционного товарищества;\n\n5) доля каждого из управляющих товарищей и товарищей в общем имуществе товарищей;\n\n6) изменения в порядке определения участником договора инвестиционного товарищества - управляющим товарищем, ответственным за ведение налогового учета, расходов, произведенных в интересах всех товарищей для ведения общих дел товарищей, в случае, если такой порядок установлен договором инвестиционного товарищества.\n\n(Дополнение пунктом - Федеральный закон от 28.11.2011 № 336-ФЗ)\n\nПри проведении налоговой проверки в отношении иностранного лица, подлежащего постановке на учет в налоговом органе в соответствии с пунктом 46 статьи 83 настоящего Кодекса, налоговый орган вправе при наличии согласия руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, истребовать информацию в отношении операций по переводу денежных средств, осуществленных в адрес указанного иностранного лица, у организации национальной системы платежных карт, операторов по переводу денежных средств, операторов электронных денежных средств, оператора платформы цифрового рубля, операционных центров, платежных клиринговых центров, центральных платежных клиринговых контрагентов, расчетных центров и операторов связи. (Дополнение абзацем - Федеральный закон от 03.07.2016 № 244-ФЗ) (В редакции  федеральных законов от 19.12.2023 № 610-ФЗ, от 29.05.2024 № 100-ФЗ)\n\nНалоговыми органами могут быть запрошены документы (информация), связанные с ведением реестра владельцев ценных бумаг, у лица, которое осуществляет (осуществляло) ведение этого реестра, в соответствии с запросом уполномоченного органа иностранного государства в случаях, предусмотренных международными договорами Российской Федерации. (Дополнение абзацем - Федеральный закон от 17.02.2021 № 6-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.06.2013 № 134-ФЗ)\n\nДолжностное лицо налогового органа, указанное в абзаце первом настоящего пункта, в случае непредставления в установленные сроки налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом) в налоговый орган документов, истребованных в соответствии с абзацем первым настоящего пункта, вправе истребовать у иных лиц, располагающих документами (информацией) об имуществе или имущественных правах налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента), эти документы (информацию). (В редакции  Федерального закона от 14.07.2022 № 263-ФЗ)\n\n(Дополнение пунктом - Федеральный закон от 29.09.2019 № 325-ФЗ)\n\nПри этом в поручении указывается, при проведении какого мероприятия налогового контроля либо что в связи с наличием задолженности возникла необходимость в представлении документов (информации), а при истребовании информации относительно конкретной сделки указываются также сведения, позволяющие идентифицировать эту сделку. (В редакции  федеральных законов от 29.09.2019 № 325-ФЗ, от 14.07.2022 № 263-ФЗ)\n\nЛицо, получившее требование о представлении документов (информации) в соответствии с пунктами 2 и 21 настоящей статьи, исполняет его в течение десяти дней со дня получения или в тот же срок уведомляет, что не располагает истребуемыми документами (информацией). (В редакции Федерального закона от 29.09.2019 № 325-ФЗ)\n\nЕсли истребуемые документы (информация) не могут быть представлены в указанные в настоящем пункте сроки, налоговый орган при получении от лица, у которого истребованы документы (информация), уведомления о невозможности представления в установленные сроки документов (информации) и о сроках (при необходимости), в течение которых эти документы (информация) могут быть представлены, вправе продлить срок представления этих документов (информации).\n\nИстребуемые документы представляются с учетом положений, предусмотренных настоящим пунктом, пунктами 2 и 5 статьи 93, пунктом 6 статьи 10529 настоящего Кодекса. (В редакции  Федерального закона от 29.12.2020 № 470-ФЗ)\n\nУказанное в настоящем пункте уведомление представляется в порядке, предусмотренном пунктом 3 статьи 93 настоящего Кодекса, если иное не предусмотрено настоящим пунктом. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\nВ случае проведения налогового мониторинга указанные в настоящем пункте документы (информация) и уведомление заверяются усиленной квалифицированной электронной подписью проверяемого лица или его представителя и представляются в налоговый орган через информационные системы организации или по телекоммуникационным каналам связи в электронной форме по форматам, установленным федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов. (Дополнение абзацем - Федеральный закон от 29.12.2020 № 470-ФЗ)\n\n(Пункт в редакции Федерального закона от 03.08.2018 № 302-ФЗ)\n\nНеправомерное несообщение (несвоевременное сообщение) истребуемой информации признается налоговым правонарушением и влечет ответственность, предусмотренную статьей 1291 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 23.07.2013 № 248-ФЗ)\n\n(Дополнение статьей - Федеральный закон от 27.07.2006 № 137-ФЗ)","article_title":"Статья 93.1. Истребование документов (информации) о налогоплательщике, плательщике сборов, плательщике страховых взносов и налоговом агенте или информации о конкретных сделках","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5076cf13a83088dc0a5b302a9dcf99ac154730896b0bdf39acbf5377ca1686a3"},{"code_id":"NK_RF","article_number":"93.2","version_date":"2000-07-31","article_text":"1. Должностное лицо налогового органа по месту учета аудиторской организации (индивидуального аудитора) вправе истребовать у аудиторской организации (индивидуального аудитора) полученные ею при осуществлении аудиторской деятельности и оказании прочих связанных с аудиторской деятельностью услуг, предусмотренных пунктами 1, 2, 4 и 5 части 7 статьи 1 Федерального закона от 30 декабря 2008 года № 307-ФЗ \"Об аудиторской деятельности\", документы (информацию) на основании решения руководителя (заместителя руководителя) федерального органа исполнительной власти, уполномоченного по контролю и надзору в области налогов и сборов, об истребовании документов (информации).\n\n2. У аудиторской организации (индивидуального аудитора) налоговым органом могут быть истребованы документы (информация), служащие основаниями для исчисления и уплаты (удержания, перечисления) налога (сбора, страховых взн\n\nосов), в случае, если такие документы (информация) были истребованы у налогоплательщика (плательщика сбора, плательщика страховых взносов, налогового агента) в соответствии с настоящим Кодексом и не были представлены в налоговый орган указанным лицом в установленном порядке при проведении в отношении его выездной налоговой проверки или проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами. В этом случае указанное в пункте 1 настоящей статьи решение должно содержать следующие сведения:\n\nреквизиты решения о проведении выездной налоговой проверки или проверки полноты исчисления и уплаты налогов в связи с совершением сделок между взаимозависимыми лицами, в рамках которых возникла необходимость истребования документов (информации) у аудиторской организации (индивидуального аудитора), предмет проверки и период, за который она проводится;\n\nдата направления налогоплательщику (плательщику сбора, плательщику страховых взносов, налоговому агенту) требования о представлении документов (информации) и срок представления истребуемых документов (информации);\n\nсведения о факте непредставления в установленный срок документов (информации) проверяемым налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом), о получении от указанного лица уведомления о невозможности представления запрашиваемых документов (информации) или о его отказе от представления запрашиваемых документов (информации);\n\nсведения об аудиторской организации (индивидуальном аудиторе), проводившей аудит и (или) оказывавшей прочие связанные с аудиторской деятельностью услуги, указанные в пункте 1 настоящей статьи, за периоды, входящие в периоды проверки: наименование организации (фамилия, имя, отчество индивидуального аудитора), государственный регистрационный номер;\n\nреквизиты или иные сведения, позволяющие идентифицировать аудиторской организацией (индивидуальным аудитором) запрашиваемые документы (информацию).\n\nТребование о представлении документов (информации) с приложением копии указанного в настоящем пункте решения направляется налоговым органом аудиторской организации (индивидуальному аудитору) после истечения срока представления в установленном порядке документов (информации) налогоплательщиком (плательщиком сбора, плательщиком страховых взносов, налоговым агентом).\n\n3. У аудиторских организаций (индивидуальных аудиторов) налоговым органом могут быть истребованы документы (информация) также при поступлении в отношении аудируемого лица запроса компетентного органа иностранного государства (территории) в случаях, предусмотренных международными договорами Российской Федерации.\n\nВ случае поступления такого запроса указанное в пункте 1 настоящей статьи решение должно содержать следующие сведения:\n\nреквизиты запроса компетентного органа иностранного государства (территории);\n\nсведения о наличии в запросе компетентного органа иностранного государства (территории) запрета на информирование лица, в отношении которого получен запрос, о передаче касающейся его информации;\n\nсведения об аудиторской организации (индивидуальном аудиторе), проводившей аудит и (или) оказывавшей прочие связанные с аудиторской деятельностью услуги, указанные в пункте 1 настоящей статьи, за периоды, входящие в периоды проверки: наименование организации (фамилия, имя, отчество индивидуального аудитора), государственный регистрационный номер;\n\nреквизиты или иные сведения, позволяющие идентифицировать аудиторской организацией (индивидуальным аудитором) запрашиваемые документы (информацию).\n\nНалоговый орган по месту учета аудиторской организации (индивидуального аудитора) направляет указанному лицу требование о представлении документов (информации) с приложением копии соответствующего решения.\n\n4. Аудиторская организация (индивидуальный аудитор) вправе информировать лицо, в отношении которого получен запрос компетентного органа иностранного государства (территории), о получении соответствующего требования налогового органа и о передаче касающейся его информации только в случае, если запрос компетентного органа иностранного государства (территории) не содержит запрета на такое информирование.\n\n5. Истребуемые документы (информация) представляются аудиторской организацией (индивидуальным аудитором) налоговому органу в течение десяти дней со дня получения соответствующего требования с учетом положений, предусмотренных пунктами 2 и 3 статьи 93 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 29.07.2018 № 231-ФЗ)","article_title":"Статья 93.2. Истребование документов (информации) у аудиторских организаций (индивидуальных аудиторов)","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5535b23741a34efe2accf48deded28ae3f676f40973c7cce83bde50ccf3c8a59"},{"code_id":"NK_RF","article_number":"94","version_date":"2000-07-31","article_text":"1. Выемка документов и предметов производится на основании мотивированного постановления должностного лица налогового органа, осуществляющего выездную налоговую проверку.\n\nУказанное постановление подлежит утверждению руководителем (его заместителем) налогового органа, вынесшего решение о проведении налоговой проверки. (В редакции Федерального закона от 16.11.2011 № 321-ФЗ)\n\n2. Не допускается производство выемки документов и предметов в ночное время.\n\n3. Выемка документов и предметов производится в присутствии понятых и лиц, у которых производится выемка документов и предметов. В необходимых случаях для участия в производстве выемки приглашается специалист.\n\nДо начала выемки должностное лицо налогового органа предъявляет постановление о производстве выемки и разъясняет присутствующим лицам их права и обязанности.\n\n4. Должностное лицо налогового органа предлагает лицу, у которого производится выемка документов и предметов, добровольно выдать их, а в случае отказа производит выемку принудительно.\n\nПри отказе лица, у которого производится выемка, вскрыть помещения или иные места, где могут находиться подлежащие выемке документы и предметы, должностное лицо налогового органа вправе сделать это самостоятельно, избегая причинения не вызываемых необходимостью повреждений запоров, дверей и других предметов.\n\n5. Не подлежат изъятию документы и предметы не имеющие отношения к предмету налоговой проверки.\n\n6. О производстве выемки, изъятия документов и предметов составляется протокол с соблюдением требований, предусмотренных статьей 99 настоящего Кодекса и настоящей статьей.\n\n7. Изъятые документы и предметы перечисляются и описываются в протоколе выемки либо в прилагаемых к нему описях с точным указанием наименования, количества и индивидуальных признаков предметов, а по возможности - стоимости предметов.\n\nПри изъятии таких документов с них изготавливают копии, которые заверяются должностным лицом налогового органа и передаются лицу, у которого они изымаются. При невозможности изготовить или передать изготовленные копии одновременно с изъятием документов, налоговый орган передает их лицу, у которого документы были изъяты, в течение пяти дней после изъятия.\n\nИзъятые документы должны быть пронумерованы, прошнурованы и скреплены печатью или подписью налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов). В случае отказа налогоплательщика (налогового агента, плательщика сбора, плательщика страховых взносов) скрепить печатью или подписью изымаемые документы об этом в протоколе о выемке делается специальная отметка. (Дополнение абзацем - Федеральный закон от 27.07.2006 № 137-ФЗ) (В редакции Федерального закона от 03.07.2016 № 243-ФЗ)","article_title":"Статья 94. Выемка документов и предметов","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"f5bf1aceb5a13a3a7ee596a700364234865bafb5fbb853b77c5afb9208007008"},{"code_id":"NK_RF","article_number":"95","version_date":"2000-07-31","article_text":"Экспертиза назначается в случае, если для разъяснения возникающих вопросов требуются специальные познания в науке, искусстве, технике или ремесле.\n\nВ постановлении указываются основания для назначения экспертизы, фамилия эксперта и наименование организации, в которой должна быть произведена экспертиза, вопросы, поставленные перед экспертом, и материалы, предоставляемые в распоряжение эксперта.\n\nПри проведении выездной налоговой проверки консолидированной группы налогоплательщиков ответственный участник этой группы подлежит ознакомлению с постановлением о назначении экспертизы. (Дополнение абзацем - Федеральный закон от 16.11.2011 № 321-ФЗ)\n\n1) заявить отвод эксперту;\n\n2) просить о назначении эксперта из числа указанных им лиц;\n\n3) представить дополнительные вопросы для получения по ним заключения эксперта;\n\n4) присутствовать с разрешения должностного лица налогового органа при производстве экспертизы и давать объяснения эксперту;\n\n5) знакомиться с заключением эксперта.\n\n10. Дополнительная экспертиза назначается в случае недостаточной ясности или полноты заключения и поручается тому же или другому эксперту.\n\nПовторная экспертиза назначается в случае необоснованности заключения эксперта или сомнений в его правильности и поручается другому эксперту.\n\nДополнительная и повторная экспертизы назначаются с соблюдением требований, предусмотренных настоящей статьей.","article_title":"Статья 95. Экспертиза","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"88eb47e24ff871c401db99640a52818717a5b149a84829f3418005faa205a760"},{"code_id":"NK_RF","article_number":"97","version_date":"2000-07-31","article_text":"Настоящее положение распространяется и на лицо, понимающее знаки немого или глухого физического лица.","article_title":"Статья 97. Участие переводчика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"532d85f179a77b17b4ce671d4157d596141c7d9168951001fabdf5d98099ba30"},{"code_id":"NK_RF","article_number":"98","version_date":"2000-07-31","article_text":"1. При проведении действий по осуществлению налогового контроля в случаях, предусмотренных настоящим Кодексом, вызываются понятые.\n\n2. Понятые вызываются в количестве не менее двух человек.\n\n3. В качестве понятых могут быть вызваны любые не заинтересованные в исходе дела физические лица.\n\n4. Не допускается участие в качестве понятых должностных лиц налоговых органов.\n\n5. Понятые обязаны удостоверить в протоколе факт, содержание и результаты действий, производившихся в их присутствии. Они вправе делать по поводу произведенных действий замечания, которые подлежат внесению в протокол.\n\nВ случае необходимости понятые могут быть опрошены по указанным обстоятельствам.","article_title":"Статья 98. Участие понятых","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"d3aade4a94e2f680811f1952d83dd159e1ca8b744ba626d6fde29a2a6d8fe916"},{"code_id":"NK_RF","article_number":"99","version_date":"2000-07-31","article_text":"1. В случаях, предусмотренных настоящим Кодексом, при проведении действий по осуществлению налогового контроля составляются протоколы. Протоколы составляются на русском языке.\n\n2. В протоколе указываются:\n\n1) его наименование;\n\n2) место и дата производства конкретного действия;\n\n3) время начала и окончания действия;\n\n4) должность, фамилия, имя, отчество лица, составившего протокол;\n\n5) фамилия, имя, отчество каждого лица, участвовавшего в действии или присутствовавшего при его проведении, а в необходимых случаях - его адрес, гражданство, сведения о том, владеет ли он русским языком;\n\n6) содержание действия, последовательность его проведения;\n\n7) выявленные при производстве действия существенные для дела факты и обстоятельства.\n\n3. Протокол прочитывается всеми лицами, участвовавшими в производстве действия или присутствовавшими при его проведении. Указанные лица вправе делать замечания, подлежащие внесению в протокол или приобщению к делу.\n\n4. Протокол подписывается составившим его должностным лицом налогового органа, а также всеми лицами, участвовавшими в производстве действия или присутствовавшими при его проведении.\n\n5. К протоколу прилагаются фотографические снимки и негативы, киноленты, видеозаписи и другие материалы, выполненные при производстве действия.","article_title":"Статья 99. Общие требования, предъявляемые к протоколу, составленному при производстве действий по осуществлению налогового контроля","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"743fb53cf4ddb34acdddecf3eb93fdcb75d5c6afc50a279d18f6316f44ae984d"},{"code_id":"NK_RF_2","article_number":"143","version_date":"2000-07-31","article_text":"организации;\n\nиндивидуальные предприниматели;\n\nлица, признаваемые налогоплательщиками налога на добавленную стоимость (далее в настоящей главе - налог) в связи с перемещением товаров через таможенную границу Таможенного союза, определяемые в соответствии с таможенным законодательством Таможенного союза и законодательством Российской Федерации о таможенном деле. (В редакции федеральных законов от 29.12.2000 № 166-ФЗ; от 27.11.2010 № 306-ФЗ)\n\nНе признаются налогоплательщиками организации, являющиеся официальными вещательными компаниям\n\nи в соответствии со статьей 31 Федерального закона от 1 декабря 2007 года № 310-ФЗ \"Об организации и о проведении XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, развитии города Сочи как горноклиматического курорта и внесении изменений в отдельные законодательные акты Российской Федерации\", в отношении операций по производству и распространению продукции средств массовой информации (в том числе по осуществлению официального теле- и радиовещания, включая цифровые и иные каналы связи), осуществляемых в соответствии с договором, заключенным с Международным олимпийским комитетом или уполномоченной им организацией, и совершаемых в течение периода проведения XXII Олимпийских зимних игр и XI Паралимпийских зимних игр 2014 года в городе Сочи, установленного частью 2 статьи 2 указанного Федерального закона.\n\n(Дополнение пунктом - Федеральный закон от 01.12.2007 № 310-ФЗ) (В редакции Федерального закона от 30.07.2010 № 242-ФЗ)\n\nНе признаются налогоплательщиками конфедерации, национальные футбольные ассоциации, производители медиаинформации FIFA, поставщики товаров (работ, услуг) FIFA, определенные указанным Федеральным законом и являющиеся иностранными организациями, в части осуществления ими операций, связанных с осуществлением мероприятий, определенных указанным Федеральным законом.\n\n(Дополнение пунктом - Федеральный закон от 07.06.2013 № 108-ФЗ)","article_title":"Статья 143. Налогоплательщики","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"580bbb8664f82ff559f7b6c9372994611e597b03e41334ed612081d99fa73e17"},{"code_id":"NK_RF_2","article_number":"144","version_date":"2000-07-31","article_text":"(Статья утратила силу - Федеральный закон от 27.07.2010 № 229-ФЗ)","article_title":"Статья 144. .","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a63b4d25bb84290a5e35497b79db01d71b1135d6ac4ee2810b4bd9a8f1ccc81b"},{"code_id":"NK_RF_2","article_number":"145","version_date":"2000-07-31","article_text":"Организации и индивидуальные предприниматели, применяющие систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), имеют право на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, при условии, что указанные лица переходят на уплату единого сельскохозяйственного налога и реализуют право, предусмотренное настоящим абзацем, в одном и том же календарном году либо при условии, что за предшествующий налоговый период по единому сельскохозяйственному налогу сумма дохода, полученного от реализации товаров (работ, услуг) при осуществлении видов предпринимательской деятельности, в отношении которых применяется указанная система налогообложения, без учета налога не превысила в совокупности: 100 миллионов рублей за 2018 год, 90 миллионов рублей за 2019 год, 80 миллионов рублей за 2020 год, 70 миллионов рублей за 2021 год, 60 миллионов рублей за 2022 год и последующие годы. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие упрощенную систему налогообложения, освобождаются от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, при соблюдении одного из следующих условий: (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nза календарный год, предшествующий календарному году, начиная с которого организация или индивидуальный предприниматель переходит на упрощенную систему налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в порядке, установленном главой 23, 25 или 261 настоящего Кодекса, а также в порядке, установленном Федеральным законом от 25 февраля 2022 года № 17-ФЗ \"О проведении эксперимента по установлению специального налогового режима \"Автоматизированная упрощенная система налогообложения\", не превысила в совокупности 60 миллионов рублей; (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nза предшествующий налоговый период по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у указанных организации или индивидуального предпринимателя сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, не превысила в совокупности 60 миллионов рублей. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВновь созданная организация и вновь зарегистрированный индивидуальный предприниматель, применяющие упрощенную систему налогообложения, освобождаются от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, начиная с даты постановки их на учет в налоговом органе, указанной в свидетельстве о постановке на учет в налоговом органе. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nПри определении величины доходов, указанной в абзацах четвертом и пятом настоящего пункта, не учитываются доходы в виде положительной курсовой разницы, предусмотренные пунктом 11 части второй статьи 250 настоящего Кодекса, и доходы в виде субсидий, признаваемые в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав). (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВ случае, если индивидуальный предприниматель применял одновременно общий режим налогообложения и патентную систему налогообложения либо систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) и патентную систему налогообложения, при определении величины доходов, указанной в абзацах четвертом и пятом настоящего пункта, учитываются доходы по обоим указанным налоговым режимам. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nВ случае, если индивидуальный предприниматель применяет (применял) в календарном году упрощенную систему налогообложения, патентную систему налогообложения, специальный налоговый режим \"Автоматизированная упрощенная система налогообложения\", при определении величины доходов в соответствии с абзацами четвертым и пятым настоящего пункта учитываются доходы по всем указанным специальным налоговым режимам. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, указанные в абзацах третьем - пятом пункта 1 настоящей статьи, применяют освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, без учета особенностей, предусмотренных абзацем первым настоящего пункта.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nЛица, указанные в абзаце первом пункта 1 настоящей статьи, использующие право на освобождение, должны представить соответствующее уведомление и документы, указанные в пункте 6 настоящей статьи, которые подтверждают право на такое освобождение, в налоговый орган по месту своего учета. (В редакции  федеральных законов от 27.11.2017 № 335-ФЗ, от 12.07.2024 № 176-ФЗ)\n\nЛица, указанные в абзаце втором пункта 1 настоящей статьи, использующие право на освобождение, должны представить соответствующее уведомление в налоговый орган по месту своего учета. (Дополнение абзацем - Федеральный закон от 27.11.2017 № 335-ФЗ) (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nУказанные документы и (или) уведомление представляются не позднее 20-го числа месяца, начиная с которого используется право на освобождение. (В редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nАбзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог), воспользовавшиеся правом на освобождение, не вправе отказаться от права на освобождение в дальнейшем, за исключением случаев, если право на освобождение будет утрачено ими в соответствии с пунктом 5 настоящей статьи.\n\nПо истечении 12 календарных месяцев не позднее 20-го числа последующего месяца организации и индивидуальные предприниматели, которые использовали право на освобождение в соответствии с абзацем первым пункта 1 настоящей статьи, представляют в налоговые органы:\n\nдокументы, подтверждающие, что в течение указанного срока освобождения сумма выручки от реализации товаров (работ, услуг), исчисленная в соответствии с пунктом 1 настоящей статьи, без учета налога за каждые 3 последовательных календарных месяца в совокупности не превышала 2 миллиона рублей;\n\nуведомление о продлении использования права на освобождение в течение последующих 12 календарных месяцев или об отказе от использования данного права.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nЕсли в течение налогового периода по единому сельскохозяйственному налогу у организации или индивидуального предпринимателя, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог) и использующих право на освобождение, сумма дохода, полученного от реализации товаров (работ, услуг) при осуществлении видов предпринимательской деятельности, в отношении которых применяется указанная система налогообложения, без учета налога превысила размер, установленный в абзаце втором пункта 1 настоящей статьи, такая организация или индивидуальный предприниматель начиная с 1-го числа месяца, в котором имело место такое превышение либо осуществлялась реализация подакцизных товаров, утрачивают право на освобождение. Организации и индивидуальные предприниматели, утратившие право на освобождение, не имеют права на повторное освобождение.\n\nЕсли в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, у организации или индивидуального предпринимателя, указанных в абзаце третьем пункта 1 настоящей статьи, сумма доходов, определяемых в соответствии со статьей 34615 и подпунктами 1 и 3 пункта 1 статьи 34625 настоящего Кодекса, превысила в совокупности 60 миллионов рублей, такие организация или индивидуальный предприниматель начиная с 1-го числа месяца, следующего за месяцем, в котором имело место такое превышение, начинает исполнять обязанности налогоплательщика. При определении величины доходов, указанной в настоящем абзаце, не учитываются доходы в виде положительной курсовой разницы, предусмотренные пунктом 11 части второй статьи 250 настоящего Кодекса, и доходы в виде субсидий, признаваемые в порядке, установленном пунктом 41 статьи 271 настоящего Кодекса, при безвозмездной передаче в государственную и (или) муниципальную собственность имущества (имущественных прав). В случае, если в течение налогового периода по налогу, уплачиваемому в связи с применением упрощенной системы налогообложения, индивидуальный предприниматель применяет одновременно упрощенную систему налогообложения и патентную систему налогообложения, при определении величины доходов, указанной в настоящем абзаце, учитываются доходы по обоим указанным специальным налоговым режимам. В случае, если в календарном году применения упрощенной системы налогообложения организации или индивидуальные предприниматели применяли специальный налоговый режим \"Автоматизированная упрощенная система налогообложения\", при определении величины доходов, указанной в настоящем абзаце, учитываются в том числе доходы, полученные в рамках применения специального налогового режима \"Автоматизированная упрощенная система налогообложения\". (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nСумма налога за месяц, в котором имело место превышение, предусмотренное абзацами первым и вторым настоящего пункта, либо осуществлялась реализация подакцизных товаров, подлежит восстановлению и уплате в бюджет в установленном порядке. (В редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nВ случае, если налогоплательщик не представил документы, указанные в пункте 4 настоящей статьи (либо представил документы, содержащие недостоверные сведения), а также в случае, если налоговый орган установил, что налогоплательщик не соблюдает ограничения, установленные настоящим пунктом и пунктами 1 и 4 настоящей статьи, сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с налогоплательщика соответствующих сумм налоговых санкций и пеней.\n\n(Пункт в редакции Федерального закона от 27.11.2017 № 335-ФЗ)\n\nвыписка из бухгалтерского баланса (представляют организации);\n\nвыписка из книги продаж;\n\nвыписка из книги учета доходов и расходов и хозяйственных операций (представляют индивидуальные предприниматели);\n\nабзац; (Утратил силу - Федеральный закон от 20.04.2014 № 81-ФЗ)\n\nДля организаций и индивидуальных предпринимателей, перешедших с упрощенной системы налогообложения на общий режим налогообложения, документом, подтверждающим право на освобождение, является выписка из книги учета доходов и расходов организаций и индивидуальных предпринимателей, применяющих упрощенную систему налогообложения. (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\nДля индивидуальных предпринимателей, перешедших на общий режим налогообложения с системы налогообложения для сельскохозяйственных товаропроизводителей (единого сельскохозяйственного налога), документом, подтверждающим право на освобождение, является выписка из книги учета доходов и расходов индивидуальных предпринимателей, применяющих систему налогообложения для сельскохозяйственных товаропроизводителей (единый сельскохозяйственный налог). (Дополнение абзацем - Федеральный закон от 17.05.2007 № 85-ФЗ)\n\nФорма и формат уведомлений, предусмотренных настоящей статьей, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, уплаченные по товарам (работам, услугам), приобретенным налогоплательщиком, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным налогоплательщиком после утраты им этого права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\nПри переходе налогоплательщика на упрощенную систему налогообложения с применением освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, предусмотренного настоящей статьей, суммы налога, принятые к вычету налогоплательщиком по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам в порядке, предусмотренном настоящей главой, подлежат восстановлению в налоговом периоде, предшествующем переходу на указанный режим. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, подлежащие восстановлению в соответствии с абзацем третьим н\n\nастоящего пункта, учитываются в составе прочих расходов в соответствии со статьей 264 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\nОрганизации и индивидуальные предприниматели, применяющие упрощенную систему налогообложения и начавшие исполнять обязанности налогоплательщика, применяющего налоговые ставки, указанные в пункте 8 статьи 164 настоящего Кодекса, суммы налога по товарам (работам, услугам), в том числе основным средствам и нематериальным активам, имущественным правам, приобретенным ими в период освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, к вычету не принимают в случае использования этих товаров (работ, услуг), в том числе основных средств и нематериальных активов, имущественных прав при осуществлении операций по реализации товаров (работ, услуг), имущественных прав, налогообложение которых производится по налоговым ставкам, указанным в подпунктах 1 - 12, 21 - 31, 7, 11 пункта 1 и пункте 8 статьи 164 настоящего Кодекса. (Дополнение абзацем - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Статья в редакции Федерального закона от 29.05.2002 № 57-ФЗ)","article_title":"Статья 145. Освобождение от исполнения обязанностей налогоплательщика","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"eec10242e2e82dff0b4fdf56fbaaa849e23cb61baa03e920f8923d3c89e8b715"},{"code_id":"NK_RF_2","article_number":"145.1","version_date":"2000-07-31","article_text":"(Наименование в редакции Федерального закона от 30.10.2018 № 373-ФЗ)\n\nПредусмотренное настоящей статьей освобождение не применяется в отношении обязанностей, возникающих в связи с ввозом на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, товаров, подлежащих налогообложению в соответствии с подпунктом 4 пункта 1 статьи 146 настоящего Кодекса. (В редакции Федерального закона от 27.11.2010 № 306-ФЗ)\n\nутрачен статус участника проекта, с момента утраты такого статуса;\n\nсовокупный размер прибыли участника проекта, рассчитанный в соответствии с главой 25 настоящего Кодекса нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки от реализации товаров (работ, услуг, имущественных прав), полученной этим участником проекта, превысил один миллиард рублей, превысил 300 миллионов рублей, с 1-го числа налогового периода, в котором произошло превышение указанного совокупного размера прибыли.\n\nСумма налога за налоговый период, в котором произошла утрата статуса участника проекта или имело место указанное превышение совокупного размера прибыли, подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с участника проекта соответствующих сумм пеней.\n\nутрачен статус участника проекта, с момента утраты такого статуса;\n\nсовокупный размер прибыли исследовательского корпоративного центра, рассчитанный в соответствии с главой 25 настоящего Кодекса нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки от реализации товаров (работ, услуг), передачи имущественных прав, полученной этим участником проекта, превысил один миллиард рублей, превысил один миллиард рублей, с 1-го числа налогового периода, в котором произошло превышение указанного совокупного размера прибыли;\n\nдоходы исследовательского корпоративного центра от реализации взаимозависимым лицам товаров (работ, услуг), передачи имущественных прав, определяемые в соответствии с главой 25 настоящего Кодекса, составили менее 50 процентов в общей сумме его доходов, с 1-го числа налогового периода, за который полученный исследовательским корпоративным центром доход от реализации взаимозависимым лицам товаров (работ, услуг), передачи имущественных прав составил менее 50 процентов в общей сумме его доходов.\n\nСумма налога за налоговый период, в котором произошла утрата статуса участника проекта, и (или) в котором имело место указанное превышение совокупного размера прибыли, и (или) в котором указанная доля дохода составила менее 50 процентов в общей сумме доходов, подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с исследовательского корпоративного центра соответствующих сумм пеней.\n\n(Дополнение пунктом - Федеральный закон от 28.12.2016 № 475-ФЗ)\n\nУчастник проекта, начавший использовать право на освобождение, должен направить в налоговый орган по месту своего учета письменное уведомление и документы, указанные в абзаце втором пункта 6 настоящей статьи, не позднее 20-го числа месяца, следующего за месяцем, с которого этот участник проекта начал использовать право на освобождение.\n\nАбзац. (Утратил силу - Федеральный закон от 12.07.2024 № 176-ФЗ)\n\n(Пункт в редакции Федерального закона от 28.12.2010 № 395-ФЗ)\n\nТакой отказ возможен только в отношении всех осуществляемых участником проекта операций.\n\nНе допускается освобождение или отказ от него в зависимости от того, кто является покупателем (приобретателем) соответствующих товаров (работ, услуг).\n\nУчастнику проекта, отказавшемуся от освобождения, оно повторно не предоставляется.\n\nдокументы, указанные в пункте 6 настоящей статьи;\n\nуведомление о продлении использования права на освобождение в течение последующих 12 календарных месяцев или об отказе от освобождения.\n\nВ случае, если участником проекта не представлены документы, указанные в пункте 6 настоящей статьи, или представлены документы, содержащие недостоверные сведения, а также в случае наличия обстоятельств, указанных в пункте 2 или 21 настоящей статьи, сумма налога подлежит восстановлению и уплате в бюджет в установленном порядке с взысканием с участника проекта соответствующих сумм пеней. (В редакции Федерального закона от 28.12.2016 № 475-ФЗ)\n\nдокументы, подтверждающие статус участника проекта и предусмотренные Федеральным законом \"Об инновационном центре \"Сколково\" либо Федеральным законом от 29 июля 2017 года № 216-ФЗ \"Об инновационных научно-технологических центрах и о внесении изменений в отдельные законодательные акты Российской Федерации\"; (В редакции Федерального закона от 30.10.2018 № 373-ФЗ)\n\nвыписка из книги учета доходов и расходов или отчет о финансовых результатах участника проекта, подтверждающие годовой объем выручки от реализации товаров (работ, услуг, имущественных прав). (В редакции федеральных законов от 28.11.2011 № 339-ФЗ; от 29.06.2012 № 97-ФЗ)\n\nНачиная с года, следующего за годом, в котором годовой объем выручки от реализации товаров (работ, услуг, имущественных прав), полученной участником проекта, превысил один миллиард рублей, участник проекта также должен представлять в налоговый орган одновременно с документами, указанными в абзацах втором и третьем настоящего пункта, предусмотренный пунктом 18 статьи 274 настоящего Кодекса расчет совокупного размера прибыли, рассчитанного нарастающим итогом начиная с 1-го числа года, в котором годовой объем выручки, полученной этим участником проекта, превысил один миллиард рублей. (В редакции Федерального закона от 28.11.2011 № 339-ФЗ)\n\nФорма и формат уведомлений, предусмотренных настоящей статьей, утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Пункт в редакции  Федерального закона от 12.07.2024 № 176-ФЗ)\n\nСуммы налога, уплаченные по товарам (работам, услугам), приобретенным участником проекта, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным им после утраты указанного права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\n(Дополнение статьей - Федеральный закон от 28.09.2010 № 243-ФЗ)","article_title":"Статья 145.1. Освобождение от исполнения обязанностей налогоплательщика организации, получившей статус участника проекта по осуществлению исследовательской и научно-технологической деятельности","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"e615c242f2c3a2f365d90dc15d39395110433d317a9b5781e614451c108a9c0f"},{"code_id":"NK_RF_2","article_number":"145.2","version_date":"2000-07-31","article_text":"1. Организация, получившая статус участника Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации в соответствии с Федеральным законом от 14 июля 2022 года № 253-ФЗ \"О Военном инновационном технополисе \"Эра\" Министерства обороны Российской Федерации и о внесении изменений в отдельные законодательные акты Российской Федерации\" (далее также - участник Технополиса) и созданная начиная с 1 января календарного года, предшествующего календарному году, в котором этой организацией подана заявка на внесение сведений в реестр участников Технополиса, имеет право на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога (далее в настоящей статье - освобождение), в порядке и на условиях, которые предусмотрены настоящей статьей.\n\nЕсли иное не установлено настоящей статьей, участник Технополиса имеет право на освобождение в течение десяти лет со дня получения статуса участника Технополиса.\n\nУчастник Технополиса имеет право на освобождение при условии, что он не применяет упрощенной системы налогообложения.\n\nПредусмотренное настоящей статьей освобождение не применяется в отношении обязанностей, возникающих в связи с ввозом на территорию Российской Федерации и иные территории, находящиеся под ее юрисдикцией, товаров, подлежащих налогообложению в соответствии с подпунктом 4 пункта 1 статьи 146 настоящего Кодекса.\n\n2. Участник Технополиса вправе использовать право на освобождение с 1-го числа месяца, следующего за месяцем, в котором был получен статус участника Технополиса, при условии представления в налоговый орган по месту своего учета не позднее 20-го числа месяца, следующего за месяцем, с которого участник Технополиса начал использовать право на освобождение, уведомления об использовании права на освобождение от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога (далее в настоящей статье - уведомление об использовании права на освобождение), в электронной форме по телекоммуникационным каналам связи или через личный кабинет налогоплательщика либо по почте заказным письмом.\n\n3. Участник Технополиса, использующий право на освобождение, вправе отказаться от освобождения, направив уведомление об отказе от освобождения от исполнения обязанностей налогоплательщика, связанных с исчислением и уплатой налога, в налоговый орган по месту своего учета в срок не позднее 1-го числа налогового периода, с которого участник Технополиса намерен отказаться от освобождения.\n\nТакой отказ возможен только в отношении всех осуществляемых участником Технополиса операций.\n\nУчастник Технополиса, отказавшийся от освобождения или утративший право на освобождение, теряет право на повторное использование права на освобождение.\n\n4. Участник Технополиса представляет в налоговый орган по месту своего учета не позднее 20 января года, следующего за истекшим календарным годом, в котором применялось освобождение, в электронной форме расчет совокупного размера полученной выручки, определенного нарастающим итогом начиная с 1-го числа года, в котором получен статус участника Технополиса.\n\nВ случае, если совокупный размер выручки, рассчитанный в соответствии с настоящим пунктом, превысил 1 миллиард рублей до истечения календарного года, последний расчет совокупного размера полученной выручки представляется не позднее 20-го числа месяца, следующего за налоговым периодом, в котором произошло указанное превышение совокупного размера полученной выручки.\n\n5. Участник Технополиса утрачивает право на освобождение в случае наступления хотя бы одного из следующих обстоятельств:\n\n1) утрачен статус участника Технополиса - со дня утраты такого статуса;\n\n2) совокупный размер полученной участником Технополиса выручки, рассчитанный в порядке, предусмотренном пунктом 4 настоящей статьи, превысил 1 миллиард рублей - с 1-го числа налогового периода, следующего за налоговым периодом, в котором произошло превышение указанного размера выручки;\n\n3) участником Технополиса не представлен в установленный срок расчет совокупного размера полученной выручки, предусмотренный пунктом 4 настоящей статьи, или представлен расчет, содержащий недостоверные сведения, - с 1-го числа календарного года, по истечении которого не представлен расчет совокупного размера полученной выручки в соответствии с пунктом 4 настоящей статьи или представлен расчет, содержащий недостоверные сведения.\n\n6. Суммы налога, принятые участником Технополиса к вычету в соответствии со статьями 171 и 172 настоящего Кодекса до использования им права на освобождение в соответствии с настоящей статьей, по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам, приобретенным для осуществления операций, признаваемых объектами налогообложения в соответствии с настоящей главой, но не использованным для указанных операций, после направления в налоговый орган участником Технополиса уведомления об использовании права на освобождение подлежат восстановлению в последнем налоговом периоде перед направлением в налоговый орган уведомления об использовании права на освобождение путем уменьшения налоговых вычетов.\n\nСуммы налога, уплаченные по товарам (работам, услугам), в том числе по основным средствам и нематериальным активам, имущественным правам, приобретенным участником Технополиса, утратившим право на освобождение в соответствии с настоящей статьей, до утраты указанного права и использованным им после утраты указанного права при осуществлении операций, признаваемых объектами налогообложения в соответствии с настоящей главой, принимаются к вычету в порядке, установленном статьями 171 и 172 настоящего Кодекса.\n\n7. Форма и формат уведомлений, предусмотренных настоящей статьей, форма и формат расчета совокупного размера выручки, порядок представления такого расчета в налоговый орган в электронной форме утверждаются федеральным органом исполнительной власти, уполномоченным по контролю и надзору в области налогов и сборов.\n\n(Дополнение статьей - Федеральный закон от 23.11.2024 № 399-ФЗ)","article_title":"Статья 145.2. Освобождение от исполнения обязанностей налогоплательщика организации, получившей статус участника Военного инновационного технополиса \"Эра\" Министерства обороны Российской Федерации","amendment_eo_number":"146-ФЗ","amendment_date":"2000-07-31","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ea5c8f4308f05792a2e890823c79829773d63056c6b3618f7924481299e5364"}]$law7d0066$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
